<script lang="ts">
 import {invalidateAll} from '$app/navigation';
 let {model,t}:{model:Record<string,Record<string,any>[]>;t:(s:string)=>string}=$props();
 let projectIds=$state<string[]>(['']),targetVolumes=$state<Record<number,string>>({}),budgets=$state<Record<number,string>>({}),ranges=$state<Record<string,string>>({}),shares=$state<Record<string,string>>({}),selected=$state<Record<string,boolean>>({}),result=$state<any>(null),busy=$state(false),message=$state(''),saveKeys=$state<Record<string,string>>({});
 async function optimize(){busy=true;message='';result=null;try{const position_ids=model.positions.filter(p=>selected[p.id]).map(p=>p.id);const plans=projectIds.filter(Boolean).map((id,j)=>({project_id:id,volume:targetVolumes[j]||model.projects.find(p=>p.id===id)?.target_l,budget:budgets[j]||model.briefs.find(b=>b.project_id===id)?.budget||undefined,shares:Object.fromEntries(position_ids.flatMap(id=>{const brief=model.briefs.find(b=>b.project_id===projectIds[j]);const min=shares[j+'_'+id+'_min']??brief?.share_limits?.[id]?.minimum,max=shares[j+'_'+id+'_max']??brief?.share_limits?.[id]?.maximum;return min||max?[[id,{minimum:min||'0',maximum:max||'100'}]]:[];})),parameters:Object.fromEntries(['alcohol','sugar','acidity'].flatMap(p=>{const brief=model.briefs.find(b=>b.project_id===projectIds[j]);const min=ranges[j+'_'+p+'_min']??brief?.targets?.[p]?.minimum,max=ranges[j+'_'+p+'_max']??brief?.targets?.[p]?.maximum;return min||max?[[p,{minimum:min||'0',maximum:max||'1000'}]]:[];}))}));const res=await fetch('/api/optimizer',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({position_ids,plans})});result=await res.json();if(!res.ok)message=t(result.message);saveKeys={};}catch{message=t('connectionError');}finally{busy=false;}}
 async function save(index:number){busy=true;try{for(const plan of result.candidates[index].plans){const key=saveKeys[index+'_'+plan.id]??crypto.randomUUID();saveKeys[index+'_'+plan.id]=key;const res=await fetch('/api/commands',{method:'POST',headers:{'content-type':'application/json','idempotency-key':key},body:JSON.stringify({type:'recipe_save',project_id:plan.id,name:t('optimizer')+' · '+result.candidates[index].objective,components:plan.components})});if(!res.ok){message=t((await res.json()).message);return;}}message=t('saved');await invalidateAll();}finally{busy=false;}}
</script>
<section class="card"><h2>{t('optimizer')}</h2><p class="muted">{t('optimizerHint')}</p><form onsubmit={(e)=>{e.preventDefault();optimize();}}><div class="sources">{#each model.positions.filter(p=>Number(p.available_l)>0).slice(0,20) as p}<label><input type="checkbox" bind:checked={selected[p.id]} /> {p.vessel_code} · {p.lot_code} · {p.available_l} L</label>{/each}</div>{#each projectIds as project,j}<fieldset><legend>{t('project_id')} {j+1}</legend><div class="grid"><label>{t('project_id')}<select bind:value={projectIds[j]} required><option value="">—</option>{#each model.projects as p}<option value={p.id}>{p.name}</option>{/each}</select></label><label>{t('target_l')}<input bind:value={targetVolumes[j]} placeholder={model.projects.find(p=>p.id===project)?.target_l??''} /></label><label>{t('budget')}<input bind:value={budgets[j]} /></label></div><div class="grid">{#each ['alcohol','sugar','acidity'] as parameter}<label>{t(parameter)} · {t('minimum')} / {t('maximum')}<div class="pair"><input aria-label={t(parameter)+' '+t('minimum')} bind:value={ranges[j+'_'+parameter+'_min']} placeholder="—" /><input aria-label={t(parameter)+' '+t('maximum')} bind:value={ranges[j+'_'+parameter+'_max']} placeholder="—" /></div></label>{/each}</div><details><summary>{t('shareLimits')}</summary>{#each model.positions.filter(p=>selected[p.id]) as p}<label>{p.vessel_code} · {p.lot_code} · %<div class="pair"><input aria-label={p.lot_code+' minimum %'} bind:value={shares[j+'_'+p.id+'_min']} placeholder="0" /><input aria-label={p.lot_code+' maximum %'} bind:value={shares[j+'_'+p.id+'_max']} placeholder="100" /></div></label>{/each}</details></fieldset>{/each}<div class="actions"><button disabled={busy}>{t('optimize')}</button>{#if projectIds.length<5}<button type="button" onclick={()=>projectIds=[...projectIds,'']}>{t('addPlan')}</button>{/if}</div></form>{#if result?.candidates}{#each result.candidates as candidate,i}<article><h3>{t(candidate.objective)} · {candidate.totalCost} €</h3>{#each candidate.plans as p}<p>{model.projects.find(project=>project.id===p.id)?.name} · {p.cost} €</p><ul>{#each p.components as c}<li>{model.positions.find(row=>row.id===c.position_id)?.lot_code} · {c.quantity_l} L</li>{/each}</ul>{#each Object.entries(p.estimates) as [parameter,value]}<p>{t(parameter)} ≈ {String(value)}</p>{/each}{/each}<details><summary>{t('remainders')}</summary>{#each candidate.remainders as r}<p>{model.positions.find(p=>p.id===r.id)?.lot_code} · {r.quantity_l} L</p>{/each}</details><button onclick={()=>save(i)} disabled={busy}>{t('saveRecipes')}</button></article>{/each}{#if !result.candidates.length}<p role="status">{t('NO_FEASIBLE_SOLUTION')}</p>{/if}{#each result.issues??[] as issue}<p class="muted">{t(issue.split(':')[0])} {issue.includes(':')?issue.slice(issue.indexOf(':')+1):''}</p>{/each}{/if}<p role="status">{message}</p></section>
<style>.sources{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:10px;margin-bottom:20px}.sources label{display:flex;align-items:center}input[type=checkbox]{width:18px;height:18px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:15px;margin:15px 0}.pair{display:flex;gap:8px}.pair input{width:50%}fieldset{border:1px solid #e1e7de;border-radius:8px;margin-bottom:16px}article{border-top:1px solid #e1e7de;padding:20px 0}.actions{display:flex;gap:10px}</style>
